customContent.css:
/* Teamder in-app — availability nudge.
   Palette is the app's own (primary #1E40AF, text #111827, muted #6B7280) so
   the card reads as part of the product, not as an ad dropped into it.
   System font stack only: the renderer's CSP allows remote fonts, but a webfont
   that fails to load would silently reshuffle the whole layout. */
* { box-sizing: border-box; margin: 0; padding: 0; }

.jr-card {
  font-family: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #FFFFFF;
  border-radius: 22px;
  overflow: hidden;
  text-align: right;
  color: #111827;
}

/* A pitch, drawn in CSS rather than shipped as an image: the renderer allows
   https images, but a hero that depends on the network is a hero that is blank
   on a bad connection — in a message that gets one appearance. */
.jr-pitch {
  position: relative;
  height: 104px;
  background:
    radial-gradient(120% 140% at 50% -30%, #2563EB 0%, #1E40AF 55%, #1E3A8A 100%);
  overflow: hidden;
}
.jr-line {
  position: absolute; inset: 0 auto 0 50%;
  width: 2px; background: rgba(255,255,255,.22);
}
.jr-circle {
  position: absolute; top: 50%; left: 50%;
  width: 76px; height: 76px; margin: -38px 0 0 -38px;
  border: 2px solid rgba(255,255,255,.22); border-radius: 50%;
}
.jr-ball {
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 34px; line-height: 1;
  filter: drop-shadow(0 6px 10px rgba(0,0,0,.28));
}

.jr-body { padding: 20px 22px 22px; }

.jr-eyebrow {
  font-size: 12px; font-weight: 700; letter-spacing: .2px;
  color: #1E40AF; margin-bottom: 6px;
}
.jr-title { font-size: 21px; font-weight: 800; line-height: 1.25; margin-bottom: 8px; }
.jr-text  { font-size: 14.5px; line-height: 1.6; color: #4B5563; margin-bottom: 18px; }

.jr-cta {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  height: 52px; border-radius: 14px;
  background: #1E40AF; color: #FFFFFF;
  font-size: 16px; font-weight: 800; text-decoration: none;
  box-shadow: 0 8px 18px rgba(30,64,175,.28);
}
/* The arrow points at the reading direction's end — in RTL that is left. */
.jr-arrow { font-size: 18px; line-height: 1; opacity: .9; }

.jr-note {
  margin-top: 10px; text-align: center;
  font-size: 11.5px; color: #6B7280;
}

/* The card is the only thing on screen at phone width; on anything wider it
   stops growing rather than stretching the headline across the viewport. */
@media (min-width: 520px) {
  .jr-card { max-width: 460px; margin: 0 auto; }
}
